import{ht as e,nt as t,o as n,tt as r}from"./chunks/framework.BDx6F-5s.js";var i=JSON.parse(`{"title":"Technical Glossary","description":"Core terminology definitions for SyncETA: Record, Scenario, Collection, Story, Dataset, MCP, Visual Regression, and Self-Healing.","frontmatter":{"title":"Technical Glossary","description":"Core terminology definitions for SyncETA: Record, Scenario, Collection, Story, Dataset, MCP, Visual Regression, and Self-Healing.","sort":1200,"head":[["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synceta/glossary.html"}]]},"headers":[],"relativePath":"en/synceta/glossary.md","filePath":"en/synceta/glossary.md","lastUpdated":1787441667000}`),a={name:`en/synceta/glossary.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="technical-glossary" tabindex="-1">Technical Glossary <a class="header-anchor" href="#technical-glossary" aria-label="Permalink to “Technical Glossary”">​</a></h1><p>Standard terminology definitions used across the SyncETA platform.</p><hr><h3 id="record" tabindex="-1">Record <a class="header-anchor" href="#record" aria-label="Permalink to “Record”">​</a></h3><p>The atomic execution unit capturing browser interactions. Stores timestamp, coordinates, XPath, CSS selectors, and DOM node metadata.</p><h3 id="scenario" tabindex="-1">Scenario <a class="header-anchor" href="#scenario" aria-label="Permalink to “Scenario”">​</a></h3><p>An ordered sequence of records representing an end-to-end user journey, including wait conditions, assertions, and recovery scripts.</p><h3 id="collection" tabindex="-1">Collection <a class="header-anchor" href="#collection" aria-label="Permalink to “Collection”">​</a></h3><p>A test suite grouping multiple scenarios for sequential or parallel batch execution.</p><h3 id="story" tabindex="-1">Story <a class="header-anchor" href="#story" aria-label="Permalink to “Story”">​</a></h3><p>A flowchart-based workflow chaining multiple scenarios within a persistent browser session.</p><h3 id="dataset" tabindex="-1">Dataset <a class="header-anchor" href="#dataset" aria-label="Permalink to “Dataset”">​</a></h3><p>A tabular key-value repository used to parameterize scenario inputs for Data-Driven Testing.</p><h3 id="playwright-mcp" tabindex="-1">Playwright MCP <a class="header-anchor" href="#playwright-mcp" aria-label="Permalink to “Playwright MCP”">​</a></h3><p>A distributed execution engine exposing browser automation tools through the Model Context Protocol (MCP) standard.</p><h3 id="visual-regression-ai" tabindex="-1">Visual Regression AI <a class="header-anchor" href="#visual-regression-ai" aria-label="Permalink to “Visual Regression AI”">​</a></h3><p>Perception-based layout inspection analyzing element overlap, text clipping, and responsive UI integrity.</p><h3 id="self-healing" tabindex="-1">Self-Healing <a class="header-anchor" href="#self-healing" aria-label="Permalink to “Self-Healing”">​</a></h3><p>An automated recovery mechanism that visualizes broken DOM selectors and proposes updated paths under Human-in-the-Loop governance.</p><h3 id="air-gapped-deployment" tabindex="-1">Air-Gapped Deployment <a class="header-anchor" href="#air-gapped-deployment" aria-label="Permalink to “Air-Gapped Deployment”">​</a></h3><p>An enterprise on-premises installation operating within fully isolated internal networks with local LLM/Vision model endpoints.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};